using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.Animations;
using LWS.TruckSports;
using LWS.TruckSports.Editor;
namespace LWS.TruckTruckGoose.Editor
{
    public static class GooseAuthoring
    {
        public const string Folder="TruckTruckGoose",Scene="Assets/TruckTruckGoose/Scenes/TruckTruckGoose.unity";
        const string Human="Assets/LWS/TruckTaxi/Passengers/Animations/Humanoid/";
        [MenuItem("Truck Sports/Alpha 0.7/Create NEW Truck Truck Goose")]
        public static void CreateNewScene(){if(File.Exists(Scene))throw new InvalidOperationException("New-scene author refuses to overwrite "+Scene);var match=SportsEventAuthoring.Begin<GooseMatch>(Folder);match.setup.count=10;match.NormalizeSetup();match.feedback.clips=ExistingAudio();Install(match);SportsEventAuthoring.UI(match);match.drivingViews=SportsDrivingViewsAuthoring.Install(match,match.trucks,match.broadcast,Folder);match.drivingViews.independentViewModes=true;SportsEventAuthoring.Save(Folder);Debug.Log("GOOSE_NEW_SCENE full NWH; bind NEW-scene appearance/weather through lead integration.");}
        static AudioClip[] ExistingAudio(){string[] paths={"Assets/Heat - Complete Modern UI/Audio/Click.wav","Assets/TruckBilliards/Audio/Ball.wav","Assets/NWH/Vehicle Physics 2/Sound/Horn/Horn.wav","Assets/TruckBilliards/Audio/Strike.wav","Assets/TruckHockey/Audio/Faceoff.wav","Assets/TruckHockey/Audio/GoalHorn.wav","Assets/TruckHockey/Audio/FinalWhistle.wav"};return paths.Select(path=>{var clip=AssetDatabase.LoadAssetAtPath<AudioClip>(path);if(clip==null)throw new InvalidOperationException("Installed sports audio required: "+path);return clip;}).ToArray();}
        public static void Install(GooseMatch match)
        {
            if(match==null||match.transform.Find("Goose playground")!=null)throw new InvalidOperationException("Install requires a new, unauthored Goose authority.");
            var root=new GameObject("Goose playground").transform;root.SetParent(match.transform,false);match.center=new GameObject("Course origin").transform;match.center.SetParent(root,false);
            var grass=SportsEventAuthoring.Mat(Folder,"Rich clover lawn",new Color(.2f,.48f,.19f),.1f);grass.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/NWH/Common/Textures/Ground/GrassAlbedo.png");grass.mainTextureScale=new Vector2(30,30);
            var contact=SportsEventAuthoring.Contact(Folder,"Playground road contact",.7f,.02f);SportsEventAuthoring.Box("Continuous physical lawn",new Vector3(0,-.6f,0),new Vector3(210,1.2f,210),grass,contact,root);
            var road=SportsEventAuthoring.Mat(Folder,"Warm rubber running track",new Color(.32f,.13f,.1f),.2f);Ring(root,match.radius-match.roadHalfWidth,match.radius+match.roadHalfWidth,.018f,road,"Continuous annular race track");
            var white=SportsEventAuthoring.Mat(Folder,"Warm cream track ink",new Color(1,.92f,.7f),.25f);foreach(float r in new[]{39f,52f,65f})Ring(root,r-.12f,r+.12f,.035f,white,"Legal course boundary");
            var wood=SportsEventAuthoring.Mat(Folder,"Honey timber play equipment",new Color(.65f,.37f,.13f),.2f);var blue=SportsEventAuthoring.Mat(Folder,"Enamel teal",new Color(.03f,.59f,.64f),.6f);var coral=SportsEventAuthoring.Mat(Folder,"Enamel coral",new Color(.95f,.23f,.19f),.55f);var metal=SportsEventAuthoring.Mat(Folder,"Brushed steel fittings",new Color(.62f,.68f,.7f),.65f);metal.SetFloat("_Metallic",.8f);
            match.trucks=new SportsEventTruck[12];for(int i=0;i<12;i++){match.trucks[i]=SpawnFullRig(match,i,match.CoursePoint(i*30,match.bayRadius),match.Heading(i*30,1));match.trucks[i].name="Goose full NWH participant "+i;}
            match.bayMarkers=new Transform[12];for(int i=0;i<12;i++){float a=i*30;Vector3 p=match.CoursePoint(a,match.bayRadius);var bay=SportsEventAuthoring.Box("Vacant-claim parking bay "+i,p-new Vector3(0,.65f,0),new Vector3(6,.03f,7),blue,null,root);bay.transform.rotation=match.Heading(a,1);match.bayMarkers[i]=bay.transform;var number=SportsEventAuthoring.Label("Bay "+i,(i+1).ToString(),p+Vector3.up*.02f,.5f,Color.white);number.transform.rotation=Quaternion.Euler(90,a,0);number.transform.SetParent(bay.transform,true);}
            // No installed slide/playset was found. These are purpose-authored detailed park structures, not stand-in boxes.
            BuildSlide(root,new Vector3(-18,0,0),blue,coral,metal,wood);BuildSlide(root,new Vector3(20,0,8),coral,blue,metal,wood);
            var pivots=new List<Transform>();for(int i=0;i<2;i++)pivots.Add(BuildSwing(root,new Vector3(-10+i*20,0,20),wood,metal,coral));
            var sand=SportsEventAuthoring.Mat(Folder,"Golden play sand",new Color(.88f,.72f,.44f),.05f);var pit=SportsEventAuthoring.Box("Recessed sandpit",new Vector3(0,.015f,-19),new Vector3(24,.05f,15),sand,null,root);for(int side=-1;side<=1;side+=2){Beam(root,new Vector3(-12,.6f,-19+side*7.5f),new Vector3(12,.6f,-19+side*7.5f),.5f,wood,"Rounded sandpit timber");Beam(root,new Vector3(side*12,.6f,-26.5f),new Vector3(side*12,.6f,-11.5f),.5f,wood,"Rounded sandpit timber");}
            for(int i=0;i<28;i++){float a=i*360f/28;SportsRallyAuthoring.Prop(root,"Assets/Toon Gas Station/Prefabs/Tree_6A.prefab",match.CoursePoint(a,84),new Vector3(9,13,9));if(i%2==0)SportsRallyAuthoring.Prop(root,"Assets/JC_LP_MegaCity/Prefabs/FloorProps/SM_FloorProps_Fence_01.prefab",match.CoursePoint(a,74),new Vector3(8,2,1));}
            var motion=root.gameObject.AddComponent<GoosePlayground>();motion.match=match;motion.swingPivots=pivots.ToArray();motion.spectators=Crowd(root,match);motion.announcement=SportsEventAuthoring.Label("Giant goose announcement","TRUCK · TRUCK · ...",new Vector3(0,12,-31),.65f,Color.white);motion.announcement.transform.SetParent(root,true);
            match.broadcast=SportsEventAuthoring.Camera("Goose Cinemachine arena");match.cameras=new[]{match.broadcast.view};match.broadcast.Pose(Vector3.zero,new Vector3(0,100,-100),60,true);
        }
        static SportsEventTruck SpawnFullRig(GooseMatch match,int slot,Vector3 position,Quaternion rotation){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(LWS.TruckFareFight.Editor.FareFightVehicleAuthoring.PrefabPath);if(prefab==null)throw new InvalidOperationException("Existing authored full NWH Fare Fight tractor required; this author never regenerates or edits that prefab.");var root=(GameObject)PrefabUtility.InstantiatePrefab(prefab);root.transform.SetPositionAndRotation(position,rotation);var facade=root.GetComponent<SportsEventTruck>();if(facade==null||facade.tractorMotor==null)throw new InvalidOperationException("Existing full NWH sport facade is required.");facade.session=match;facade.slot=slot;facade.tractorMotor.settings=match.settings;EditorUtility.SetDirty(facade);EditorUtility.SetDirty(facade.tractorMotor);return facade;}
        static void BuildSlide(Transform parent,Vector3 p,Material chute,Material accent,Material steel,Material wood)
        {
            var root=new GameObject("Purpose-authored giant curved slide").transform;root.SetParent(parent,false);root.position=p;
            for(int side=-1;side<=1;side+=2){Beam(root,new Vector3(side*3,0,-7),new Vector3(side*3,10,-7),.35f,wood,"Tower post");Beam(root,new Vector3(side*3,0,-12),new Vector3(side*3,10,-12),.35f,wood,"Tower post");for(int step=0;step<12;step++)Beam(root,new Vector3(-2,step*.75f,-15+step*.27f),new Vector3(2,step*.75f,-15+step*.27f),.12f,steel,"Actual ladder rung");}
            SportsEventAuthoring.Box("Timber slide platform",new Vector3(0,9,-9),new Vector3(7,.5f,7),wood,null,root);
            for(int i=0;i<32;i++){float t=i/31f,u=(i+1)/31f;Vector3 a=new Vector3(Mathf.Sin(t*Mathf.PI)*3,9*(1-t)*(1-t)+.4f,-6+t*22),b=new Vector3(Mathf.Sin(u*Mathf.PI)*3,9*(1-u)*(1-u)+.4f,-6+u*22);var strip=SportsEventAuthoring.Box("Continuous curved slide tread",(a+b)*.5f,new Vector3(4,.18f,Vector3.Distance(a,b)+.04f),chute,null,root);strip.transform.localRotation=Quaternion.LookRotation(b-a);for(int side=-1;side<=1;side+=2)Beam(root,a+new Vector3(side*2,.6f,0),b+new Vector3(side*2,.6f,0),.14f,accent,"Rolled slide safety rail");}
        }
        static Transform BuildSwing(Transform parent,Vector3 p,Material wood,Material metal,Material seat)
        {
            var root=new GameObject("Giant playground swing gantry").transform;root.SetParent(parent,false);root.position=p;for(int x=-1;x<=1;x+=2)for(int z=-1;z<=1;z+=2)Beam(root,new Vector3(x*5,0,z*5),new Vector3(x*4,13,0),.35f,wood,"A-frame bolted leg");Beam(root,new Vector3(-5,13,0),new Vector3(5,13,0),.45f,metal,"Swing axle");var pivot=new GameObject("Moving suspended swing").transform;pivot.SetParent(root,false);pivot.localPosition=Vector3.up*12;for(int side=-1;side<=1;side+=2)Beam(pivot,new Vector3(side*2,0,0),new Vector3(side*2,-9,0),.06f,metal,"Suspension chain");SportsEventAuthoring.Box("Sculpted swing seat",new Vector3(0,-9,0),new Vector3(5,.45f,2.5f),seat,null,pivot);return pivot;
        }
        static Animator[] Crowd(Transform root,GooseMatch match)
        {
            string controllerPath="Assets/TruckTruckGoose/Materials/Playground crowd.controller";var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(controllerPath);if(controller==null)controller=AnimatorController.CreateAnimatorControllerAtPath(controllerPath);
            foreach(string name in new[]{"Idle","Cheer"}){var machine=controller.layers[0].stateMachine;var state=machine.states.FirstOrDefault(s=>s.state.name==name).state;if(state==null)state=machine.AddState(name);if(state.motion==null)state.motion=AssetDatabase.LoadAllAssetsAtPath(Human+(name=="Idle"?"idle1":"cheer")+".FBX").OfType<AnimationClip>().First(c=>c.humanMotion&&!c.name.StartsWith("__"));if(name=="Idle")machine.defaultState=state;EditorUtility.SetDirty(state);EditorUtility.SetDirty(machine);}EditorUtility.SetDirty(controller);AssetDatabase.SaveAssets();
            var people=new List<Animator>();for(int i=0;i<24;i++){string gender=i%2==0?"business01_m":"business01_f";string path=i%2==0?"Assets/UTS_FullPack/Models/People/Prefabs/Mans/business01_m.prefab":"Assets/UTS_FullPack/Models/People/Prefabs/Womans/business01_f_highpoly.prefab";var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(path);var avatarModel=AssetDatabase.LoadAssetAtPath<GameObject>(Human+gender+".FBX");if(prefab==null||avatarModel==null)throw new InvalidOperationException("Owned humanoid model required.");var actor=UnityEngine.Object.Instantiate(avatarModel,root);actor.name="Real humanoid playground spectator "+i;foreach(var script in actor.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(script);foreach(var col in actor.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(col);var animator=actor.GetComponentInChildren<Animator>(true);var source=avatarModel.GetComponent<Animator>();if(animator==null||source==null||source.avatar==null||!source.avatar.isHuman)throw new InvalidOperationException("Genuine shared humanoid avatar required.");animator.avatar=source.avatar;animator.runtimeAnimatorController=controller;animator.applyRootMotion=false;animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;actor.transform.position=match.CoursePoint(i*15,71);actor.transform.rotation=Quaternion.LookRotation(-Vector3.ProjectOnPlane(actor.transform.position,Vector3.up));actor.transform.localScale=Vector3.one*2.5f;people.Add(animator);}return people.ToArray();
        }
        static void Beam(Transform root,Vector3 a,Vector3 b,float r,Material mat,string name){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=name;g.transform.SetParent(root,false);g.transform.localPosition=(a+b)*.5f;g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);g.transform.localScale=new Vector3(r*2,(b-a).magnitude*.5f,r*2);g.GetComponent<Renderer>().sharedMaterial=mat;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());}
        static void Ring(Transform root,float inner,float outer,float y,Material material,string name){int n=192;var v=new Vector3[(n+1)*2];var uv=new Vector2[v.Length];var t=new int[n*6];for(int i=0;i<=n;i++){float a=i*Mathf.PI*2/n;v[i*2]=new Vector3(Mathf.Sin(a)*inner,y,Mathf.Cos(a)*inner);v[i*2+1]=new Vector3(Mathf.Sin(a)*outer,y,Mathf.Cos(a)*outer);uv[i*2]=new Vector2(i/12f,0);uv[i*2+1]=new Vector2(i/12f,1);if(i<n){int k=i*6,j=i*2;t[k]=j;t[k+1]=j+1;t[k+2]=j+2;t[k+3]=j+1;t[k+4]=j+3;t[k+5]=j+2;}}var mesh=new Mesh{name=name};mesh.vertices=v;mesh.uv=uv;mesh.triangles=t;mesh.RecalculateNormals();mesh.RecalculateTangents();var g=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(root,false);g.GetComponent<MeshFilter>().sharedMesh=mesh;g.GetComponent<MeshRenderer>().sharedMaterial=material;AssetDatabase.CreateAsset(mesh,"Assets/TruckTruckGoose/Materials/"+name.Replace(' ','_')+"_"+inner.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture)+".asset");}
    }
}
